-- A sidecar as the v3.0.0 release actually wrote it: `sqlite3 .dump` of a
-- database produced by running that build's own storage API through a full
-- round, then stamped with the `user_version` it left (`.dump` omits it).
--
-- v3.0.0 is `LAUNCH_VERSION`, the oldest sidecar the ladder upgrades in place
-- rather than resetting, so this is the oldest input the in-place path
-- promises to handle. Bundle 0 is a completed round: delegated, proved, cast,
-- confirmed, with its helper share accepted. Bundle 1 stops with its
-- delegation on chain and no vote cast — the state `van_comm_rand` exists for,
-- which an upgrade may never lose. Proposal 3 is deliberately skipped, and the
-- second vote carries the pre-rc.13 recovery JSON that the version 16 to 17
-- rung rewrites.
--
-- Generated, not authored. Do not hand-edit; regenerate from a v3.0.0
-- worktree if the oldest supported sidecar ever needs to change.
PRAGMA user_version = 13;

PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE rounds (
    round_id            TEXT NOT NULL,
    wallet_id           TEXT NOT NULL DEFAULT '',
    network             TEXT NOT NULL CHECK (network IN ('mainnet', 'testnet', 'regtest')),
    snapshot_height     INTEGER NOT NULL,
    ea_pk               BLOB NOT NULL,
    nc_root             BLOB NOT NULL,
    nullifier_imt_root  BLOB NOT NULL,
    session_json        TEXT,
    phase               INTEGER NOT NULL DEFAULT 0,
    created_at          INTEGER NOT NULL,
    PRIMARY KEY (round_id, wallet_id)
);
